1	/**
2	 * Validate any pipeline JSON against the contract, from the command line.
3	 *
4	 *   npm run validate --prefix contract -- path/to/your.json
5	 *   npm run validate --prefix contract            # defaults to data/pipeline.json
6	 *
7	 * This exists so the Python module owners can check merge.py output without
8	 * running the frontend. Exit code 1 on failure, so it drops into a script.
9	 */
10	import { readFileSync } from "node:fs";
11	import { resolve } from "node:path";
12	import { fileURLToPath } from "node:url";
13	import { parsePipeline } from "./contract.ts";
14	
15	// fileURLToPath, not URL.pathname: on Windows the latter yields "/C:/..."
16	// which resolves to a nonexistent "C:\C:\..." path.
17	const DEFAULT = fileURLToPath(new URL("../data/pipeline.json", import.meta.url));
18	const target = process.argv[2] ? resolve(process.argv[2]) : DEFAULT;
19	
20	let raw: unknown;
21	try {
22	  raw = JSON.parse(readFileSync(target, "utf8"));
23	} catch (error) {
24	  console.error(`Could not read ${target}`);
25	  console.error(`  ${error instanceof Error ? error.message : String(error)}`);
26	  process.exit(1);
27	}
28	
29	const result = parsePipeline(raw);
30	
31	if (!result.ok) {
32	  console.error(`✕ ${target} does not satisfy the contract\n`);
33	  for (const problem of result.problems) console.error(`  ${problem}`);
34	  console.error(
35	    "\nThe contract is app/src/lib/contract.ts. If the shape changed on " +
36	      "purpose, update it there, update data/pipeline.json, and tell the team.",
37	  );
38	  process.exit(1);
39	}
40	
41	const { meta, funnel, candidates, graveyard } = result.data;
42	const survivors = candidates.filter((c) => c.verdict === "survived").length;
43	
44	console.log(`✓ ${target} satisfies the contract`);
45	console.log(
46	  `  ${funnel.length} stages · ${candidates.length} candidates ` +
47	    `(${survivors} surviving) · ${graveyard.length} graveyard entries`,
48	);
49	if (meta.sample) {
50	  console.log("  ⚠ meta.sample is true — the UI will show the sample-data badge");
51	}
52

